  while (_floorEntityCache.size > MAX_MEMORY_FLOORS) {
    let furthestKey = null, maxDist = -1;
    for (const key of _floorEntityCache.keys()) {
      const m = /^z(\d+):/.exec(String(key));
      const depth = m ? (Number(m[1]) | 0) : 0;
